"""The memory home: the folder `autoMemoryDirectory` names, with a folder per repository under it."""
import json
import os
import pathlib
import re
import subprocess


def git(folder, *args):
    run = subprocess.run(["git", "-C", folder, *args], capture_output=True, text=True)
    return run.stdout.strip() if run.returncode == 0 else ""


def main_checkout(cwd):
    """The folder of the main checkout that holds `cwd`, else None."""
    if not isinstance(cwd, str) or not os.path.isdir(cwd):
        return None
    common = git(cwd, "rev-parse", "--path-format=absolute", "--git-common-dir")
    if not common:
        top = git(cwd, "rev-parse", "--show-toplevel")
        return top or None
    common = pathlib.Path(common)
    return str(common.parent) if common.name == ".git" else str(common)


def repository(cwd):
    """The folder name of a repository: its origin's name, else its main checkout's folder name."""
    root = main_checkout(cwd)
    if not root:
        return None
    url = git(root, "config", "--get", "remote.origin.url").rstrip("/")
    name = re.split(r"[/:\\]", url)[-1] if url else ""
    name = name[:-4] if name.endswith(".git") else name
    return name or os.path.basename(root) or None


def setting(path):
    try:
        with open(path, encoding="utf-8") as handle:
            value = json.load(handle).get("autoMemoryDirectory")
    except (OSError, ValueError, AttributeError):
        return None
    if not isinstance(value, str) or not value:
        return None
    if value == "~" or value.startswith("~/"):
        value = os.path.expanduser(value)
    return value


def home(cwd, config):
    """The home: the main checkout's `.claude/settings.local.json`, then `<config>/settings.json`; None when unset."""
    root = main_checkout(cwd)
    found = setting(os.path.join(root, ".claude", "settings.local.json")) if root else None
    return found or setting(os.path.join(str(config), "settings.json"))


